// Xác định loại thư theo giờ Việt Nam
const now = DateTime.now().setZone('Asia/Ho_Chi_Minh');
let mode = 'nhac';                          // Thứ Sáu 14:00: nhắc người chưa gửi báo cáo tuần này
if (now.weekday === 5 && now.hour >= 16) mode = 'nhac_lai';   // Thứ Sáu 16:30: nhắc lại người vẫn chưa gửi
if (now.weekday === 1) mode = 'tong_hop';   // Thứ Hai 08:30: gửi Trưởng phòng tổng hợp tuần trước
const ref = mode === 'tong_hop' ? now.minus({ days: 3 }) : now;
return [{ json: { mode, p_week: ref.toFormat("kkkk-'W'WW") } }];

// Soạn danh sách thư từ kết quả app_weekly_digest
const d = $input.first().json;
const mode = $('Xác định tuần').first().json.mode;
const td = 'style="padding:4px 8px;border:1px solid #e4e9f1"';
const out = [];
if (mode !== 'tong_hop') {
  for (const s of d.staff) {
    if (!s.email || !s.open || s.submitted) continue;            // chỉ nhắc người còn việc mở và chưa gửi
    out.push({ json: { to: s.email, subject: (mode === 'nhac_lai' ? '[NHẮC LẠI] ' : '') + s.subject, html: s.html } });
  }
} else {
  const staff = d.staff.filter((s) => s.role !== 'manager');
  const done = staff.filter((s) => s.submitted).length;
  const rows = staff.map((s) => `<tr><td ${td}>${s.name}</td><td ${td} align="right">${s.open}</td><td ${td} align="right" style="color:#b91c1c">${s.overdue}</td><td ${td}>${s.submitted ? '<span style="color:#15803d">Đã gửi</span>' : '<b style="color:#b45309">Chưa gửi</b>'}</td></tr>`).join('');
  const html = `<div style="font-family:Segoe UI,Arial,sans-serif;font-size:14px;color:#172033"><p>Kính gửi Trưởng phòng,</p>
<p>Tổng hợp báo cáo tiến độ nhiệm vụ tuần <b>${d.week}</b>: <b>${done}/${staff.length}</b> cán bộ đã gửi.${d.missing.length ? ' Chưa gửi (còn việc mở): <b>' + d.missing.join(', ') + '</b>.' : ''}</p>
<table style="border-collapse:collapse;font-size:13px"><tr style="background:#172033;color:#fff"><th ${td}>Cán bộ</th><th ${td}>Việc mở</th><th ${td}>Quá hạn</th><th ${td}>BC tuần</th></tr>${rows}</table>
<p><a href="https://tien-do-goi-thau.vercel.app/#/nhiem-vu?tab=xh" style="color:#ee0033;font-weight:bold">Mở bảng xếp hạng & thống kê</a></p>
<p style="color:#586579;font-size:12px">Thư tự động — hệ thống Điều hành gói thầu, hợp đồng & nhiệm vụ.</p></div>`;
  for (const m of d.staff.filter((s) => s.role === 'manager' && s.email)) out.push({ json: { to: m.email, subject: `[P.QLHT] Tổng hợp báo cáo tuần ${d.week}: ${done}/${staff.length} đã gửi`, html } });
}
return out;
